569	    run: (ctx) => scan(codeTs(ctx), /\bElementRef\b/g),
570	  },
571	  {
572	    id: "forwardref-displayname",
573	    name: "forwardRef without displayName",
574	    why: "An anonymous forwardRef shows as ForwardRef in React DevTools and error stacks; pass a named function or set displayName.",
575	    run: (ctx) => {
576	      const v = [];
577	      for (const f of codeTs(ctx))
578	        for (const m of f.code.matchAll(/(?:const|let)\s+(\w+)\s*=\s*(?:React\.)?forwardRef\b/g)) {
579	          if (new RegExp(`\\b${m[1]}\\.displayName\\s*=`).test(f.code)) continue;
580	          if (namedFunctionArg(f.code, m.index + m[0].length)) continue;
581	          v.push({ file: f.path, line: lineOf(f.code, m.index), match: short(m[0]) });
582	        }
583	      return v;
584	    },
585	  },
586	  {
587	    id: "variant-on-package-class",
588	    name: "Tailwind variant on a DS package class",
589	    why: "ds-*, h-button*, size-button* and text-style-* are plain package CSS, not Tailwind utilities, so hover:/data-[…]: variants on them emit no rule and silently do nothing.",
590	    run: (ctx) => scan(tsx(ctx),
591	      /(?<![\w-])(?:[\w-]+|\[[^\]\s]+\]):(?:ds-[\w-]+|h-button[\w-]*|size-button[\w-]*|text-style-[\w-]+)/g),
592	  },
593	  {
594	    id: "svg-var-attribute",
595	    name: "var() in SVG geometry attributes",
596	    why: "SVG 2 parses a presentation attribute as a value, not a declaration, so var() in a geometry attribute (width, r, cx …) is not specified: Chromium draws it, but its SVG DOM reads the length as 0; keep a plain number attribute and set the token through style or a class.",
597	    run: (ctx) => {
598	      // Only host elements (lowercase tags) carry SVG attributes; <DropdownMenuSection width="var(…)">
599	      // is a component PROP. The attribute pattern skips quoted strings and {…} expressions.
600	      const attrs = String.raw`(?:[^>"'{}]|"[^"]*"|'[^']*'|\{(?:[^{}]|\{(?:[^{}]|\{[^{}]*\})*\})*\})*?`;
601	      const re = new RegExp(String.raw`<[a-z][\w.-]*\b${attrs}\s((?:width|height|r|rx|ry|x|y|cx|cy|x1|x2|y1|y2)=(?:["']|\{\s*["'\x60]?)[^"'\x60}]*var\(--)`, "gd");
602	      const v = [];
603	      for (const f of tsx(ctx))
604	        for (const m of f.code.matchAll(re))
605	          v.push({ file: f.path, line: lineOf(f.code, m.indices[1][0]), match: short(m[1]) });
606	      return v;
607	    },
608	  },
609	  {
610	    id: "theme-detection",
611	    name: "runtime theme detection",
612	    why: "Dark mode is CSS only (.dark and the tokens); detecting the theme in JS breaks nested dark islands and renders differently on the server.",
613	    run: (ctx) => scan(codeTs(ctx), /prefers-color-scheme|classList\.(?:contains|toggle|add)\(\s*["']dark/g),
614	  },
615	  {
616	    id: "font-family",
617	    name: "hardcoded font families",
618	    why: "A literal font stack bypasses the --ui-font-* tokens, so a consumer font override never reaches it.",
619	    run: (ctx) => scan(
620	      ctx.files.filter((f) => !f.generated && f.rel !== TOKENS_REL && !f.rel.startsWith("components/Text/")),
621	      /font-family:(?!\s*(?:var\(|inherit))[^;]+;|fontFamily:\s*["'`](?!var\()/g),
622	  },
623	  {
624	    id: "variant-const-name",
625	    name: "variant constants named *Type",
626	    why: "Dot-accessible option constants are named *Variant (or *Size); a *Type name reads as a TypeScript type. DropdownMenuSelectType is the sanctioned exception: it holds the selectType prop's values.",
627	    run: (ctx) => scan(codeTs(ctx), /export\s+const\s+(\w+?Types?)\s*=/g, (m) => !SANCTIONED_TYPE_CONSTS.has(m[1])),
628	  },
629	  {
630	    id: "size-key-name",
631	    name: "size keys named default or small",
632	    why: "A size scale calls its default size standard and its small size sm, never default or small, so the same size reads the same on every component; only size scales (…Size consts and cva size groups) are held to this, not variant keys.",
633	    run: (ctx) => {
634	      const v = [];
635	      for (const f of codeTs(ctx)) {
636	        // A size scale: a `…Size` / `…Sizes` const object, or the `size: { … }` group of a cva.
637	        const opens = new Set();
638	        for (const m of f.code.matchAll(/(?:export\s+)?const\s+\w+Sizes?\s*=\s*\{/g)) opens.add(m.index + m[0].length - 1);
639	        for (const m of f.code.matchAll(/(?<![\w$.?])size\s*:\s*\{/g)) opens.add(m.index + m[0].length - 1);
640	        for (const open of opens) {
641	          const body = f.code.slice(open, closingBrace(f.code, open));
642	          for (const m of body.matchAll(/(?<![\w$.-])["']?(default|small)["']?\s*:/g))
643	            v.push({ file: f.path, line: lineOf(f.code, open + m.index), match: short(m[0]) });
644	        }
645	      }
646	      return v;
647	    },
648	  },
649	  {
650	    id: "expression-system",
651	    name: "expression tokens set or read outside the expression system",
652	    why: "Expression tokens are set only by the tokens.css :root default and the practical preset, and read only by .ds-expr-* rules: a set anywhere else overrides the preset in that subtree, so practical stops switching it; a read anywhere else scatters the detail where the next edit cannot find it; and a marked token missing from the preset is one practical cannot switch off.",
653	    run: expressionSystem,
654	  },
655	  {
656	    id: "dark-theme",
657	    name: "dark aliases missing from .dark, and redundant .dark lines",
658	    why: "An alias resolves where it is declared, so a nested .dark island keeps the light value unless .dark repeats the alias; a .dark line that repeats a non-alias :root value re-declares the DS value on every nested .dark island, so a consumer's :root override never reaches them.",
659	    run: darkTheme,
660	  },
661	  {
662	    id: "dark-outside-tokens",
663	    name: "dark-mode rules or hex colours outside tokens.css",
664	    why: "Dark mode lives in tokens.css alone: a component paints with a token and tokens.css gives it its dark value. A .dark selector, a dark variant (@variant dark, @custom-variant dark) or a hex colour in a component stylesheet, or a dark: variant in a class string, skips the token, so it ignores consumer overrides, and a .dark rule also reaches into a nested .light island. No stylesheet, tokens.css included, reads prefers-color-scheme: following the OS scheme is the consuming app's job, and a media query would override the app's own light/dark choice. The #000 mask-image stops in index.css are allowlisted: a mask reads only alpha.",
665	    run: darkOutsideTokens,
666	  },
667	  {
668	    id: "use-client",
669	    name: "\"use client\" outside its allowlist",
670	    why: "\"use client\" makes a module a client boundary, and constants declared in it become references a server component cannot read; only modules that need client-only React or browser APIs carry it, each listed with its reason.",
671	    run: useClient,
672	  },
673	  {
674	    id: "js-timers",
675	    name: "JS timers and animation loops outside their allowlist",
676	    why: "A JS timer that mirrors a CSS duration desyncs the moment either is retuned; motion timing lives in CSS on the motion scale, so each timer or rAF loop is listed with its reason.",
677	    run: jsTimers,
678	  },
679	  {
680	    id: "theme-fresh",
681	    name: "generated theme out of date",
682	    why: "index.css's @theme block, theme.css and twMergeTheme.ts are generated from tokens.css by sync-theme.mjs; stale output ships utilities and cn() merges that disagree with the tokens.",
683	    fixtures: false,
684	    run: () => runCheckMode("scripts/sync-theme.mjs"),
685	  },
686	  {
687	    id: "icons-fresh",
688	    name: "icon barrel out of date",
689	    why: "src/components/Icons/index.ts is generated from the *Icon.tsx files by generate-icon-exports.mjs; a stale barrel leaves a new icon out of the package entry or exports one whose file is gone.",
690	    fixtures: false,
691	    run: () => runCheckMode("scripts/generate-icon-exports.mjs"),
692	  },
693	  {
694	    id: "shape-morph-ease-fresh",
695	    name: "shape-morph ease out of date",
696	    why: "The --ui-shape-morph-duration and --ui-shape-morph-ease block in tokens.css is generated from the spring in shapeMorphSpring.mjs by generate-shape-morph-ease.mjs; a hand edit, or a retuned spring that was not regenerated, makes the morph's timing disagree with its spring.",
697	    fixtures: false,
698	    run: () => runCheckMode("scripts/generate-shape-morph-ease.mjs"),
699	  },
700	  {
701	    id: "docs-fresh",
702	    name: "generated doc references out of date",
703	    why: "components.md, token-contract.md, the codebase inventory and the client-references list are generated from src/ by generate-docs.mjs and read as the truth by agents and consumers; a stale one documents props, defaults, tokens, files or client boundaries that no longer match the code.",
704	    fixtures: false,
705	    run: () => runCheckMode("scripts/generate-docs.mjs"),
706	  },
707	  {
708	    id: "skills-mirrored",
709	    name: "skill mirrors out of sync with .agents/skills",
710	    why: "agents load skills from .claude/skills and .agent/skills, which are real copies of .agents/skills made by sync-skills.mjs; a stale, missing or symlinked mirror makes an agent follow an outdated skill or none at all.",
711	    fixtures: false,
712	    run: () => runCheckMode("scripts/sync-skills.mjs"),
713	  },
714	];
715	
716	// ── Main ──────────────────────────────────────────────────────────────────────
717	const argv = process.argv.slice(2);
718	const fi = argv.indexOf("--fixtures");
719	const fixtureMode = fi !== -1;
720	const root = fixtureMode
721	  ? path.resolve(REPO, argv[fi + 1] && !argv[fi + 1].startsWith("--") ? argv[fi + 1] : DEFAULT_FIXTURES)
722	  : path.join(REPO, "src");
723	
724	const files = loadFiles(root);
725	const ctx = {
726	  mode: fixtureMode ? "fixtures" : "src",
727	  root,
728	  rootRel: repoRel(root),
729	  files,
730	  byPath: new Map(files.map((f) => [f.path, f])),
731	  tokens: files.find((f) => f.rel === TOKENS_REL) || null,
732	  allowlists: { useClient: USE_CLIENT_ALLOWLIST, timers: TIMER_ALLOWLIST, stylesheetHex: STYLESHEET_HEX_ALLOWLIST },
733	};
734	if (fixtureMode) {
735	  const p = path.join(root, "allowlists.json");
736	  const j = fs.existsSync(p) ? JSON.parse(fs.readFileSync(p, "utf8")) : {};
737	  const at = (e) => ({ ...e, file: repoRel(path.join(root, e.file)) });
738	  ctx.allowlists = { useClient: (j.useClient || []).map(at), timers: (j.timers || []).map(at), stylesheetHex: (j.stylesheetHex || []).map(at) };
739	}
740	
741	const active = CHECKS.filter((c) => !fixtureMode || c.fixtures !== false);
742	const results = active.map((c) => ({ check: c, violations: c.run(ctx) }));
743	for (const { check, violations } of results)
744	  for (const x of violations) console.log(`FAIL ${check.name}: ${x.file}:${x.line} ${x.match}`);
745	const failed = results.filter((r) => r.violations.length);
746	
747	if (!fixtureMode) {
748	  if (failed.length) {
749	    console.log("");
750	    for (const { check } of failed) console.log(`why (${check.name}): ${check.why}`);
751	    console.log(`\nconventions: ${failed.length} of ${CHECKS.length} checks failed`);
752	    process.exit(1);
753	  }
754	  console.log(`conventions: ${CHECKS.length} checks passed`);
755	  process.exit(0);
756	}
757	
758	// Fixture mode: every <check-id>[.<case>].<ext> file is reported exactly once, by its own check.
759	const ids = new Set(active.map((c) => c.id));
760	const problems = [];
761	const byFile = new Map();
762	for (const { check, violations } of results)
763	  for (const x of violations) {
764	    if (!byFile.has(x.file)) byFile.set(x.file, []);
765	    byFile.get(x.file).push(check.id);
766	  }
767	for (const { check, violations } of results) if (!violations.length) problems.push(`BROKEN ${check.id}: reported nothing`);
768	const expectOf = (rel) => {
769	  const parts = path.posix.basename(rel).split(".");
770	  return ids.has(parts[0]) && !(parts.length > 2 && parts[1] === "ok") ? parts[0] : null;
771	};
772	const seen = new Set();
773	for (const f of files) {
774	  seen.add(f.path);
775	  const want = expectOf(f.rel);
776	  const got = byFile.get(f.path) || [];
777	  if (want && (got.length !== 1 || got[0] !== want))
778	    problems.push(`MISMATCH ${f.path}: expected exactly one report from ${want}, got [${got.join(", ")}]`);
779	  if (!want && got.length) problems.push(`UNEXPECTED ${f.path}: must report nothing, got [${got.join(", ")}]`);
780	}
781	for (const [file, got] of byFile) if (!seen.has(file)) problems.push(`UNEXPECTED ${file}: not a fixture file, got [${got.join(", ")}]`);
782	
783	console.log("");
784	for (const c of active) {
785	  const caught = results.find((r) => r.check === c).violations.map((x) => path.posix.basename(x.file));
786	  console.log(`${caught.length ? "caught" : "BROKEN"}  ${c.id.padEnd(26)} ${caught.join(", ")}`);
787	}
788	const skipped = CHECKS.filter((c) => c.fixtures === false).map((c) => c.id);
789	if (skipped.length) console.log(`skipped (repo-level, no fixtures): ${skipped.join(", ")}`);
790	for (const p of problems) console.log(p);
791	console.log(problems.length
792	  ? `\nfixtures: ${problems.length} problem(s)`
793	  : `\nfixtures: OK — ${active.length} checks, each caught exactly its own fixtures (${files.length} files)`);
794	process.exit(problems.length ? 1 : 0);
795

